 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number, vatRate: number }>, dueDate?: string, voucher?: { code: string, amount: number }, payments?: Array<any> }} invoice
 * @returns {string} plain-text invoice
 */
export function renderInvoiceText(invoice) {
  // Get customer info
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) {
    throw new Error(`Customer not found: ${invoice.customerId}`);
  }
  const customer = customerResult.value;

  const lines = [];

  // First line: invoice number or DRAFT
  const invoiceNumber = invoice.number || 'DRAFT';
  lines.push(invoiceNumber);

  // Second line: customer name
  lines.push(customer.name);

  // Invoice lines
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const discount = lineDiscount(line);
    if (discount > 0) {
      const lineText = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)} (less ${line.discountPercent}% = ${formatEuros(discount)}) = ${formatEuros(total - discount)}`;
      lines.push(lineText);
    } else {
      const lineText = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
      lines.push(lineText);
    }
  }

  // Totals
  const totals = invoiceTotals(invoice);
  const hasDiscount = totals.discount > 0;
  const hasVat = totals.vat > 0;

  if (hasDiscount || hasVat) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
  }
  if (hasDiscount) {
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }
  if (hasVat) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Voucher (if any)
  if (invoice.voucher && invoice.voucher.amount > 0) {
    lines.push(`Voucher: -${formatEuros(invoice.voucher.amount)}`);
  }

  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Due date (if invoice has one)
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid amount (if invoice has payments)
  const paid = invoice.payments ? invoice.payments.reduce((sum, p) => sum + p.amount, 0) : 0;
  if (paid > 0) {
    lines.push(`Paid: ${formatEuros(paid)}`);
  }

  return lines.join('\n');
}

