3	import { renderInvoiceText } from '../src/render.js';
4	import { createInvoice, issueInvoice } from '../src/invoices.js';
5	
6	test('renderInvoiceText shows DRAFT for unsent invoices', () => {
7	  const r = createInvoice({
8	    customerId: 'C-002', // standard tier, no discount
9	    issueDate: '2024-01-15',
10	    lines: [{ sku: 'DES-HOUR', qty: 1 }],
11	  });
12	  assert.equal(r.ok, true);
13	  const text = renderInvoiceText(r.value);
14	  assert.match(text, /^DRAFT\n/);
15	});
16	
17	test('renderInvoiceText shows invoice number when issued', () => {
18	  const r1 = createInvoice({
19	    customerId: 'C-002', // standard tier, no discount
20	    issueDate: '2024-01-15',
21	    lines: [{ sku: 'DES-HOUR', qty: 1 }],
