test('renderInvoiceText shows all elements in correct order', () => {
  let r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
