test('renderInvoiceText shows all elements in correct order', () => {
  let r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
  const r2 = applyVoucher(r1.value, { code: 'SUMMER', amount: 1000 });
  assert.equal(r2.ok, true);
  const r3 = issueInvoice(r2.value, []);
  assert.equal(r3.ok, true);
  const r4 = recordPayment(r3.value, { amount: 5000, date: '2024-01-20' });
  assert.equal(r4.ok, true);
  const text = renderInvoiceText(r4.value);
  const lines = text.split('\n');

  // Find line indices
  const voucherIndex = lines.findIndex(l => l.startsWith('Voucher:'));
  const totalIndex = lines.findIndex(l => l.startsWith('Total:'));
  const dueIndex = lines.findIndex(l => l.startsWith('Due:'));
  const paidIndex = lines.findIndex(l => l.startsWith('Paid:'));

  assert(voucherIndex >= 0, 'Should have voucher line');
  assert(totalIndex >= 0, 'Should have total line');
  assert(dueIndex >= 0, 'Should have due date line');
  assert(paidIndex >= 0, 'Should have paid line');
  assert(totalIndex > voucherIndex, 'Total should come after voucher');
  assert(dueIndex > totalIndex, 'Due date should come after total');
  assert(paidIndex > dueIndex, 'Paid should come after due date');
});

